// Generated by Skyramp Testbot from source analysis of
// apps/admin-x-settings/src/components/MemberGrowthChart.tsx (PR #64).
//
// EXPECTED FAILURE. MemberGrowthChart is not imported, mounted or rendered by any
// production file, so [data-testid="member-growth-chart"] has no DOM node anywhere in
// the running admin app. This spec was written from the component source rather than
// recorded, because recording it against any other page would validate a surface the
// PR did not change. It starts passing once the component is wired into a route and
// admin credentials are supplied via the workflow's uiCredentials input.

import {expect, test} from '@playwright/test';

const ADMIN_URL = process.env.SKYRAMP_TEST_BASE_URL ?? 'http://localhost:2368';
const ADMIN_EMAIL = process.env.SKYRAMP_UI_USERNAME ?? '';
const ADMIN_PASSWORD = process.env.SKYRAMP_UI_PASSWORD ?? '';

test('member growth chart renders a zero peak for a period with no signups', async ({page}) => {
    test.setTimeout(60000);

    await page.goto(`${ADMIN_URL}/ghost/#/signin`);
    await page.waitForLoadState('networkidle');

    await page.getByLabel('Email address').fill(ADMIN_EMAIL);
    await page.getByLabel('Password').fill(ADMIN_PASSWORD);
    await page.getByRole('button', {name: 'Sign in'}).click();
    await page.waitForURL(/#\/(dashboard|analytics|posts)/, {timeout: 30000});

    await page.goto(`${ADMIN_URL}/ghost/#/settings`);
    await page.waitForLoadState('networkidle');

    const chart = page.locator('[data-testid="member-growth-chart"]');
    await chart.waitFor({state: 'visible', timeout: 10000});

    // Empty-data branch: data.length === 0 renders the empty-state message and no bars.
    await expect(chart.locator('[data-testid="no-data-message"]'))
        .toHaveText('No data available for this period');
    await expect(chart.locator('[data-testid="bar-0"]')).toHaveCount(0);

    // The footer statistics still render for an empty series. Math.max(...[]) evaluates to
    // -Infinity, so peak-value currently prints "-Infinity" instead of "0".
    await expect(chart.locator('[data-testid="total-count"]')).toHaveText('0');
    await expect(chart.locator('[data-testid="peak-value"]')).toHaveText('0');

    // The requested window is echoed back even when the series is empty.
    await expect(chart.locator('[data-testid="date-range"]')).toContainText(' to ');
});
